(function() {
    // 1. 기존 저장된 소중한 역/마커 데이터 불러오기
    var savedData = localStorage.getItem('hyobin_markers');
    if (savedData) {
        try {
            var parsed = JSON.parse(savedData);
            if (Array.isArray(parsed) && parsed.length > 0) window.myLandmarks = parsed;
        } catch(e) {}
    }
    if (!window.myLandmarks) window.myLandmarks = [];

    // 2. ★ 최강의 방어막 (로컬 스토리지 폭파 원천 차단)
    // 브라우저가 데이터를 저장하려고 할 때 중간에 가로채서, 5800개 정류장만 쏙 빼고 저장시킵니다.
    if (!window._isLocalStorageShielded) {
        var originalSetItem = localStorage.setItem;
        localStorage.setItem = function(key, value) {
            if (key === 'hyobin_markers') {
                try {
                    var arr = JSON.parse(value);
                    // 'isHardcoded' 꼬리표가 붙은 5800개 정류장은 빼고 저장 (용량 초과 방지)
                    var filtered = arr.filter(function(m) { return !m.isHardcoded; });
                    value = JSON.stringify(filtered);
                } catch(e) {}
            }
            originalSetItem.call(this, key, value);
        };
        window._isLocalStorageShielded = true;
    }

    // 3. 5,800개 정류장 안전하게 장전
    if (typeof hardcodedBusStops !== 'undefined' && typeof addMarkerToMap === 'function') {
        hardcodedBusStops.forEach(function(s) {
            s.isHardcoded = true; // ★ 용량 터짐 방지용 꼬리표 부착!
            
            // 사용자가 수동으로 편집한 정류장이면 덮어쓰지 않음
            var exists = window.myLandmarks.some(function(m) {
                return m.type === 'busStop' && m.name === s.name && Math.abs(m.lat - s.lat) <= 10;
            });
            
            if (!exists) {
                addMarkerToMap(s); // 지도에 그리기
                window.myLandmarks.push(s); // ★ 버스 노선 패널(타임라인) 100% 작동하게 함
                if (typeof window.allLandmarks !== 'undefined') {
                    window.allLandmarks.push(s); // 검색 엔진 작동하게 함
                }
            }
        });
    }
})();